{
  "gate_token": "BoyURxy7fZvRuQbW0docaA",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is unrolled at the edge of the ruined city.",
      "visual_description": "Mara crouches on a cracked cobblestone hill, unrolling a vellum map weighted with stones, the broken skyline of the royal city smoldering in the distance.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp warns of more than one trap.",
      "visual_description": "An oil lamp held aloft, its single flame-eye narrowed, casting long shadows over Mara's worried face as banners flap on a distant gate.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout is wound up for the mission.",
      "visual_description": "A small tin fox sits on a stone bench as Mara turns the brass key in its tail, blue glass eyes flickering to life beneath a torn royal banner.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The rescuer arrives through a shattered window.",
      "visual_description": "Glass Diver emerges headfirst from a tall broken window as if swimming up out of water, helmet fogged, coat shimmering with reflected firelight.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team studies the castle gates from cover.",
      "visual_description": "Four figures crouched behind a toppled fountain, peering at iron-spiked castle gates strung with old gold-and-crimson banners.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a winged beast drift from a cursed tower.",
      "visual_description": "A leaning black tower wreathed in green smoke looms above the rooftops; Oracle Lamp's eye-flame flares as Mara shakes her head and points the other way.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The fox slips between armored patrols.",
      "visual_description": "Tin Fox darts low through a colonnade, brass paws silent on the flagstones, while spear-tips and lantern-light pass overhead on the upper walk.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "An official is found snoring on a barrel of stamped papers.",
      "visual_description": "Sleeping Tax Collector slumped over a ledger pillow, stamped writs glued to his sleeves, a quill drooping from his fingers as Tin Fox sniffs his boot.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "He mumbles a passcode without waking.",
      "visual_description": "Glass Diver leans close to the slumped official, ear to his lips, while Mara scribbles syllables onto the margin of her map by lamplight.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Frightened faces watch from boarded windows.",
      "visual_description": "Narrow alley lined with shuttered houses, pale eyes glinting between planks; Mara raises an open palm in peace as Tin Fox trots ahead.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "A magic door refuses to open.",
      "visual_description": "Tall door of black glass covered in moving silver runes; Glass Diver presses a gloved hand to its surface, ripples spreading like water.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The rescuer dives into the door as if into a pond.",
      "visual_description": "Glass Diver plunges shoulder-first into the rune-door, half his coat already gone into shimmer, helmet trailing a wake of light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Inside, mirrors show the missing person.",
      "visual_description": "A round mirrored chamber: dozens of reflections of a chained captive, only one of them moving, Glass Diver reaching toward the true one.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The lamp shouts a warning through the glass.",
      "visual_description": "Oracle Lamp pressed against an outer mirror, flame-eye huge and alarmed, Mara behind it gesturing urgently while Glass Diver looks up inside.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The fox triggers a distraction in the courtyard.",
      guidance: 0,
      "visual_description": "Tin Fox leaps onto a brass bell rope, pulling it down; bells crash and torches scatter as armored figures rush off-panel toward the noise.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The captive is pulled back through the mirror.",
      "visual_description": "Glass Diver emerges from the rune-door dragging a blanket-wrapped figure, water-light pouring off them onto the cracked marble floor.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The team races for the river bridge.",
      "visual_description": "A long stone bridge over a dark river at dawn; Mara, Glass Diver carrying the rescued figure, and Tin Fox sprint across as banners burn behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "On the far bank, the lamp finally dims to a soft glow.",
      "visual_description": "The group rests on a mossy embankment beyond the bridge; Oracle Lamp's flame-eye half-closed, Tin Fox curled at Mara's feet, Glass Diver removing his fogged helmet as the ruined city smolders across the water.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

